INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1424076', 'Battle of Mursa Major', 'The Battle of Mursa was fought on 28 September 351 between the eastern Roman armies led by the Emperor Constantius II and the western forces supporting the usurper Magnentius. It took place at Mursa, near the Via Militaris in the province of Pannonia (modern Osijek, Croatia).', 351, 9, 28, NULL, NULL, NULL, 'day', '28 September 351', 55, 'https://en.wikipedia.org/wiki/Battle_of_Mursa_Major'),
  ('Q841211', 'Battle of Nedao', 'The Battle of Nedao was fought in Pannonia in 454 between the Huns and their former vassals or allies. The Nedao is believed to be a tributary of the Sava.', 454, NULL, NULL, NULL, NULL, NULL, 'year', '454', 65, 'https://en.wikipedia.org/wiki/Battle_of_Nedao'),
  ('Q3440376', 'Siege of Trsat', 'The siege of Trsat (Croatian: Opsada Trsata) was a battle fought over possession of the town of Trsat (Latin: Tarsatica) in Liburnia, near the Croatian–Frankish border. The battle was fought in the autumn of 799 between the defending forces of Dalmatian Croatia under the leadership of Croatian duke Višeslav, and the invading Frankish army of the Carolingian Empire led by Eric of Friuli.', 799, NULL, NULL, NULL, NULL, NULL, 'year', '799', 39, 'https://en.wikipedia.org/wiki/Siege_of_Trsat'),
  ('Q22158904', 'Siege of Ragusa', 'The siege of Ragusa (modern Dubrovnik in Croatia) by the Aghlabids of Ifriqiya lasted for fifteen months, beginning in 866 until the lifting of the siege upon the approach of a Byzantine fleet in 868. The failure of the siege and the re-appearance of the Byzantines in the region of Dalmatia signalled the beginning of new aggressive western policy by the new Byzantine emperor, Basil I. Its immediate effects were the re-establishment of Byzantine authority there in the form of the Theme of Dalmatia, and the beginning of the Christianization of the Slavs of the western Balkans, but within a…', 866, NULL, NULL, 868, NULL, NULL, 'year', '866–868', 53, 'https://en.wikipedia.org/wiki/Siege_of_Ragusa_(866%E2%80%93868)'),
  ('Q12627973', 'Battle of Makarska', 'The Battle of Makarska was a major confrontation on the sea between Slavic Narentine pirates and Republic of Venice, which occurred on 18 September 887.', 887, 9, 18, NULL, NULL, NULL, 'day', '18 September 887', 39, 'https://en.wikipedia.org/wiki/Battle_of_Makarska'),
  ('Q842361', 'Battle of Gvozd Mountain', 'The Battle of Gvozd Mountain took place in 1097 and was fought between the army of Petar Snačić and King Coloman I of Hungary. It was a decisive Hungarian victory, which ended the War of the Croatian Succession and served as a turning point in Croatian history.', 1097, NULL, NULL, NULL, NULL, NULL, 'year', '1097', 51, 'https://en.wikipedia.org/wiki/Battle_of_Gvozd_Mountain'),
  ('Q604739', 'Siege of Zara', 'The siege of Zara or siege of Zadar (Croatian: opsada Zadra; Hungarian: Zára ostroma; 10–24 November 1202) was the first major action of the Fourth Crusade and the first attack against a Catholic city by Catholic crusaders. The crusaders had an agreement with Venice for transport across the sea, but the price far exceeded what they were able to pay.', 1202, 11, 10, 1202, 11, 24, 'day', '10 November 1202 – 24 November 1202', 65, 'https://en.wikipedia.org/wiki/Siege_of_Zara'),
  ('Q27465472', 'Siege of Zadar', 'The siege of Zadar (12 August 1345 – 21 December 1346) was a successful attempt of the Republic of Venice to capture Zadar (or Zara), a Croatian coastal city in northern Dalmatia. It was a combined land and sea offensive by the Venetians, consisting of many separate battles and operations against the citizens of Zadar, who refused to accept Venetian suzerainty and demanded autonomy.', 1345, 8, 12, 1346, 12, 21, 'day', '12 August 1345 – 21 December 1346', 41, 'https://en.wikipedia.org/wiki/Siege_of_Zadar_(1345%E2%80%931346)'),
  ('Q18713116', 'Siege of Knin', 'The siege of Knin (Croatian: Opsada Knina) was a siege of the city of Knin, the capital of the Kingdom of Croatia, by the Ottoman Empire in 1522. After two failed attempts in 1513 and 1514, Ottoman forces led by Ghazi Husrev Bey, sanjak-bey (governor) of the Sanjak of Bosnia, launched a major offensive on southern Croatia in the spring of 1522.', 1522, 5, NULL, 1522, 5, 29, 'month', 'May 1522 – 29 May 1522', 39, 'https://en.wikipedia.org/wiki/Siege_of_Knin'),
  ('Q735043', 'Siege of Klis', 'The siege of Klis or Battle of Klis (Croatian: Opsada Klisa, Bitka kod Klisa, Turkish: Klise Kuşatması) was a siege of Klis Fortress in the Kingdom of Croatia within Habsburg monarchy. The siege of the fortress, which lasted for more than two decades, and the final battle near Klis in 1537, were fought as a part of the Ottoman–Habsburg wars between the defending Croatian–Habsburg forces under the leadership of Croatian feudal lord Petar Kružić, and the attacking Ottoman army under the leadership of the Ottoman general Murat-beg Tardić.', 1536, 8, 31, 1537, 3, 12, 'day', '31 August 1536 – 12 March 1537', 43, 'https://en.wikipedia.org/wiki/Siege_of_Klis'),
  ('Q7510063', 'Siege of Gvozdansko', 'The siege of Gvozdansko (Croatian: Opsada Gvozdanskog) was an Ottoman siege of the fort of Gvozdansko in the Kingdom of Croatia in 1577–1578. In the 1570s, the Ottomans intensified their efforts to capture the valley of the Una River.', 1578, 1, 13, 1578, 1, 13, 'day', '13 January 1578', 41, 'https://en.wikipedia.org/wiki/Siege_of_Gvozdansko'),
  ('Q701335', 'Battle of Sisak', 'The Battle of Sisak was fought on 22 June 1593 between Ottoman Bosnian forces and a combined Christian army from the Habsburg lands, mainly the Kingdom of Croatia and Inner Austria. The battle took place at Sisak, central Croatia, at the confluence of the Sava and Kupa rivers, on the borderland between Christian Europe and the Ottoman Empire.', 1593, 6, 22, NULL, NULL, NULL, 'day', '22 June 1593', 60, 'https://en.wikipedia.org/wiki/Battle_of_Sisak'),
  ('Q255006', 'Magnate conspiracy', 'The Magnate Conspiracy (also known as the Zrinski–Frankopan Conspiracy (Croatian: Zrinsko-frankopanska urota) in Croatia, and the Wesselényi Conspiracy (Hungarian: Wesselényi-összeesküvés) in Hungary, was a plot among Croatian and Hungarian nobles to oust the Habsburg Monarchy from Croatia and Hungary, in response to the Treaty of Vasvár in 1664. This treaty – which ended the Fourth Austro-Turkish War – was highly unpopular in the Military Frontier, and those who were involved in the conspiracy intended to reopen hostilities with the Ottoman Empire after they broke away from Habsburg rule.', 1670, NULL, NULL, NULL, NULL, NULL, 'decade', '1670s', 57, 'https://en.wikipedia.org/wiki/Magnate_conspiracy'),
  ('Q18199199', 'Siege of Ragusa', 'The siege of Ragusa took place in 1806 during the Napoleonic Wars (the War of the Third Coalition in a certain period). After French occupied the maritime republic of Ragusa, Russian and allied forces under the leadership of Vice Admiral Dmitry Senyavin laid siege to it for months.', 1806, 5, 26, 1806, 6, NULL, 'day', '26 May 1806 – June 1806', 39, 'https://en.wikipedia.org/wiki/Siege_of_Ragusa_(1806)'),
  ('Q2618441', '1880 Zagreb earthquake', 'The 1880 earthquake which struck Zagreb, and is also known as The Great Zagreb earthquake, occurred with a moment magnitude of 6.3 on 9 November 1880. Its epicenter was in the Medvednica mountain north of Zagreb.', 1880, 11, 9, NULL, NULL, NULL, 'day', '9 November 1880', 56, 'https://en.wikipedia.org/wiki/1880_Zagreb_earthquake'),
  ('Q56063289', 'Fiume enterprise', 'In the aftermath of the First World War, the Fiume question was the dispute regarding the postwar fate of the city of Rijeka (Italian: Fiume) and its surroundings. As an element of the Adriatic question, the dispute arose from competing claims by the Kingdom of Italy and the short-lived State of Slovenes, Croats and Serbs carved out in the process of the dissolution of Austria-Hungary.', 1919, 9, 12, 1920, 12, 27, 'day', '12 September 1919 – 27 December 1920', 47, 'https://en.wikipedia.org/wiki/Fiume_question'),
  ('Q3870643', 'Bloody Christmas', 'The Bloody Christmas (Croatian: Riječki krvavi božić; Italian: Natale di sangue) of 1920 was a series of clashes in Fiume (now Rijeka, Croatia), which led to the conclusion of the Fiume campaign that was carried out by the Italian poet, adventurer, and proto-fascist Gabriele D''Annunzio in 1920.', 1920, 12, 29, 1920, 12, 29, 'day', '29 December 1920', 39, 'https://en.wikipedia.org/wiki/Bloody_Christmas_(1920)'),
  ('Q12959187', 'Gata massacre', 'The Gata massacre was the murder of 96 villagers in the Croatian village of Gata in 1942. The perpetrators of this massacre were members of Momčilo Đujić''s Dinara Chetnik Division, under the leadership of Commander (vojvode) Mane Rokvić.', 1942, 10, 1, NULL, NULL, NULL, 'day', '1 October 1942', 39, 'https://en.wikipedia.org/wiki/Gata_massacre'),
  ('Q3442408', 'Daksa massacre', 'The Daksa massacre, also called the Daksa executions, refers to the war crime summary execution of 53 men, accused of collaboration, by Yugoslav Partisans on 24–25 October 1944 during World War II on the Croatian island of Daksa, near Dubrovnik. After the Partisans entered Dubrovnik on 18 October 1944, they arrested more than 300 citizens.', 1944, 10, 24, NULL, NULL, NULL, 'day', '24 October 1944', 39, 'https://en.wikipedia.org/wiki/Daksa_massacre'),
  ('Q16983329', 'Aviogenex Flight 130', 'Aviogenex Flight 130 was an international charter passenger flight from Gatwick Airport, London to Rijeka Airport, Yugoslavia (modern-day Croatia). On 23 May 1971, the Tupolev Tu-134A servicing the flight suffered structural failure during landing.', 1971, 5, 23, NULL, NULL, NULL, 'day', '23 May 1971', 45, 'https://en.wikipedia.org/wiki/Aviogenex_Flight_130'),
  ('Q2288824', 'Dinamo Zagreb–Red Star Belgrade riot', 'The Dinamo Zagreb–Red Star Belgrade riot was a football riot which took place on 13 May 1990 at Maksimir Stadium in Zagreb, SR Croatia, then part of SFR Yugoslavia, between the Bad Blue Boys (supporters of Dinamo Zagreb) and the Delije (supporters of Red Star Belgrade). The incident took place just weeks after Croatia''s first multi-party elections in almost fifty years in which the parties favouring Croatian independence had won the majority of votes.', 1990, 5, 13, NULL, NULL, NULL, 'day', '13 May 1990', 60, 'https://en.wikipedia.org/wiki/Dinamo%E2%80%93Red_Star_riot'),
  ('Q503678', 'Saborsko massacre', 'The Saborsko massacre (Pokolj u Saborskom, Operacija Saborsko) was the killing of 29 Croat residents of the village of Saborsko on 12 November 1991, following the seizure of the village in a Yugoslav People''s Army (Jugoslovenska Narodna Armija – JNA) and Croatian Serb offensive during the Croatian War of Independence. The fall of the town occurred as part of a JNA and Croatian Serb operation to capture a Croatian-held pocket centered on the town of Slunj, southeast of Karlovac.', 1991, 11, 12, NULL, NULL, NULL, 'day', '12 November 1991', 41, 'https://en.wikipedia.org/wiki/Saborsko_massacre'),
  ('Q505939', 'Battle of Vukovar', 'The Battle of Vukovar was an 87-day siege of Vukovar in eastern Croatia by the Yugoslav People''s Army (JNA), supported by various paramilitary forces from Serbia, between August and November 1991. Before the Croatian War of Independence the Baroque town was a prosperous, mixed community of Croats, Serbs and other ethnic groups.', 1991, 8, 25, 1991, 11, 18, 'day', '25 August 1991 – 18 November 1991', 71, 'https://en.wikipedia.org/wiki/Battle_of_Vukovar'),
  ('Q520741', 'Vukovar massacre', 'The Vukovar massacre, also known as the Vukovar hospital massacre or the Ovčara massacre, was the killing of at least 200 Croatian prisoners of war and civilians by Serb paramilitaries, to whom they had been turned over by the Yugoslav People''s Army (JNA), at the Ovčara farm southeast of Vukovar on 20 November 1991, during the Croatian War of Independence. The massacre occurred shortly after Vukovar''s capture by the JNA, Territorial Defence (TO), and paramilitaries from neighbouring Serbia.', 1991, 11, 20, 1991, 11, 21, 'day', '20 November 1991 – 21 November 1991', 62, 'https://en.wikipedia.org/wiki/Vukovar_massacre'),
  ('Q526104', 'Dalj massacre', 'The Dalj massacre was the killing of Croats in Dalj, Croatia from 1 August 1991 until June 1992, during the Croatian War of Independence. In addition to civilian victims, the figure includes 20 Croatian policemen, 15 Croatian National Guard (Zbor narodne garde – ZNG) troops and four civil defencemen who had been defending the police station and water supply building in the village on 1 August 1991.', 1991, 8, 1, NULL, NULL, NULL, 'day', '1 August 1991', 48, 'https://en.wikipedia.org/wiki/Dalj_massacre'),
  ('Q663501', 'Operation Swath-10', 'Operation Swath-10 (Croatian: Operacija Otkos-10) was a military offensive undertaken by the Croatian Army (Hrvatska vojska, or HV) against the SAO Western Slavonia Territorial Defense Forces on Bilogora Mountain in western Slavonia. Occurring from 31 October to 4 November 1991, during the Croatian War of Independence, the operation was a Croatian victory and its success set the stage for follow-up advances by Croatian forces on Papuk Mountain in Operation Papuk-91 in late November and December.', 1991, 10, 31, 1991, 11, 4, 'day', '31 October 1991 – 4 November 1991', 41, 'https://en.wikipedia.org/wiki/Operation_Swath-10'),
  ('Q815140', 'Siege of Dubrovnik', 'The siege of Dubrovnik (Serbo-Croatian: opsada Dubrovnika, опсада Дубровника) was a military campaign fought between the Yugoslav People''s Army (JNA) and Croatian forces defending the city of Dubrovnik and its surroundings during the Croatian War of Independence. The JNA started its advance on 1 October 1991, and by late October, it had captured virtually all the land between the Pelješac and Prevlaka peninsulas on the coast of the Adriatic Sea, with the exception of Dubrovnik itself.', 1991, 10, 1, 1992, 5, 31, 'day', '1 October 1991 – 31 May 1992', 66, 'https://en.wikipedia.org/wiki/Siege_of_Dubrovnik'),
  ('Q852157', 'Plitvice Lakes incident', 'The Plitvice Lakes incident (Croatian: Krvavi Uskrs na Plitvicama or Plitvički krvavi Uskrs, both translating as "Plitvice Bloody Easter") was an armed clash at the beginning of the Croatian War of Independence. It was fought between Croatian police and armed forces from the Croatian Serb-established SAO Krajina at the Plitvice Lakes in Croatia, on 31 March 1991.', 1991, 3, NULL, NULL, NULL, NULL, 'month', 'March 1991', 57, 'https://en.wikipedia.org/wiki/Plitvice_Lakes_incident'),
  ('Q1243060', 'Gospić massacre', 'The Gospić massacre was the mass killing of 100–120 predominantly Serb civilians in Gospić, Croatia, during the last two weeks of October 1991, during the Croatian War of Independence. The majority of the victims were ethnic Serbs arrested in Gospić and the nearby coastal town of Karlobag.', 1991, 10, 25, NULL, NULL, NULL, 'day', '25 October 1991', 55, 'https://en.wikipedia.org/wiki/Gospi%C4%87_massacre'),
  ('Q1470352', 'Škabrnja massacre', 'The Škabrnja massacre was the killing of 62 Croatian civilians and 5 prisoners of war by Serbian Autonomous Oblast Krajina (SAO Krajina) Territorial Defence troops and the Yugoslav People''s Army (JNA) in the villages of Škabrnja and Nadin east of Zadar on 18–19 November 1991, during the Croatian War of Independence. Ten more people were killed by 11 March 1992.', 1991, 11, 19, NULL, NULL, NULL, 'day', '19 November 1991', 43, 'https://en.wikipedia.org/wiki/%C5%A0kabrnja_massacre'),
  ('Q1621069', 'Lovas killings', 'The Lovas killings (Croatian: masakr u Lovasu, Serbian: zločini u Lovasu, злочини у Ловасу) involved the killing of 70 Croat civilian residents of the village of Lovas between 10 and 18 October 1991, during the Croatian War of Independence. The killings took place during and in the immediate aftermath of the occupation of the village by the Yugoslav People''s Army (JNA) supported by Croatian Serb forces and Dušan the Mighty Forces.', 1991, 10, 10, 1991, 10, 18, 'day', '10 October 1991 – 18 October 1991', 47, 'https://en.wikipedia.org/wiki/Lovas_killings'),
  ('Q1851834', 'Battle of Borovo Selo', 'The Battle of Borovo Selo of 2 May 1991, known in Croatia as the Borovo Selo massacre (Croatian: Pokolj u Borovom Selu) and in Serbia as the Borovo Selo incident (Serbian: Инцидент у Боровом Селу), was one of the first armed clashes in the conflict which became known as the Croatian War of Independence. The clash was precipitated by months of rising ethnic tensions, violence, and armed combat in Pakrac and at the Plitvice Lakes in March.', 1991, 5, 2, NULL, NULL, NULL, 'day', '2 May 1991', 53, 'https://en.wikipedia.org/wiki/Battle_of_Borovo_Selo'),
  ('Q2354422', 'Battle of the Dalmatian channels', 'The Battle of the Dalmatian Channels was a three-day confrontation between three tactical groups of Yugoslav Navy ships and coastal artillery, and a detachment of naval commandos of the Croatian Navy fought on 14–16 November 1991 during the Croatian War of Independence. On 14 November, the commandos torpedoed the Mirna-class patrol boat PČ-176 Mukos close to the island of Brač in the Split Channel of the Adriatic Sea, prompting a Yugoslav naval bombardment of Brač and Šolta Island the same day.', 1991, 11, 14, 1991, 11, 16, 'day', '14 November 1991 – 16 November 1991', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_Dalmatian_Channels'),
  ('Q2613862', 'Voćin massacre', 'The Voćin massacre was the killing of 43 civilians in Voćin, Croatia, by the Serbian White Eagles paramilitary unit on 13 December 1991, during the Croatian War of Independence. The massacre was carried out after the unit was ordered to abandon the village before the Croatian Army (Hrvatska vojska – HV) recaptured the area in Operation Papuk-91.', 1991, 12, 13, NULL, NULL, NULL, 'day', '13 December 1991', 47, 'https://en.wikipedia.org/wiki/1991_Vo%C4%87in_massacre'),
  ('Q2624653', 'Battle of the Barracks', 'The Battle of the Barracks (Croatian: Bitka za vojarne) was a series of engagements that occurred in mid-to-late 1991 between the Croatian National Guard (ZNG, later renamed the Croatian Army) and the Croatian police on one side and the Yugoslav People''s Army (JNA) on the other. The battle took place around numerous JNA posts in Croatia, starting when Croatian forces blockaded the JNA barracks, weapons storage depots and other facilities.', 1991, 9, 14, 1991, 11, 23, 'day', '14 September 1991 – 23 November 1991', 51, 'https://en.wikipedia.org/wiki/Battle_of_the_Barracks'),
  ('Q3512544', 'Joševica massacre', 'The Joševica massacre was a war crime committed by the paramilitary forces of the Krajina Serbs in the Croatian village of Joševica during the Croatian War of Independence. The atrocities took place on 16 December 1991.', 1991, 12, 16, NULL, NULL, NULL, 'day', '16 December 1991', 39, 'https://en.wikipedia.org/wiki/Jo%C5%A1evica_massacre'),
  ('Q3514508', 'Baćin massacre', 'The Baćin massacre was the killing of 83 civilians just outside the village of Baćin, near Hrvatska Dubica, committed by Croatian Serb paramilitaries. The killings took place on 21 October 1991 during the Croatian War of Independence.', 1991, 10, 21, NULL, NULL, NULL, 'day', '21 October 1991', 39, 'https://en.wikipedia.org/wiki/Ba%C4%87in_massacre'),
  ('Q4111833', 'Battle of Osijek', 'The Battle of Osijek (Serbo-Croatian: Bitka za Osijek) was the artillery bombardment of the Croatian city of Osijek by the Yugoslav People''s Army (JNA) which took place from August 1991 to June 1992 during the Croatian War of Independence. Shelling peaked in late November and December 1991, then diminished in 1992 after the Vance plan was accepted by the combatants.', 1991, 8, NULL, 1992, 6, NULL, 'month', 'August 1991 – June 1992', 50, 'https://en.wikipedia.org/wiki/Battle_of_Osijek'),
  ('Q4871132', 'Battle of Gospić', 'The Battle of Gospić (Serbian: Битка за Госпић, Croatian: Bitka za Gospić) was fought in the environs of Gospić, Croatia, from 29 August until 22 September 1991 during the Croatian War of Independence. The battle pitted the Yugoslav People''s Army (JNA), stationed in five barracks in the town, and paramilitary elements of the Serbian Guard against the Croatian National Guard (ZNG), police forces based in Gospić and police reinforcements from elsewhere in Croatia.', 1991, 8, 29, 1991, 9, 22, 'day', '29 August 1991 – 22 September 1991', 39, 'https://en.wikipedia.org/wiki/Battle_of_Gospi%C4%87'),
  ('Q4873058', 'Battle of Šibenik', 'The Battle of Šibenik (Croatian: Bitka za Šibenik), also known as the September War (Rujanski rat), was an armed conflict fought between the Yugoslav People''s Army (Jugoslovenska Narodna Armija – JNA), supported by the Croatian Serb-established Serbian Autonomous Oblast of Krajina (SAO Krajina), and the Croatian National Guard (Zbor Narodne Garde – ZNG), supported by the Croatian Police. The battle was fought to the north and west of the city of Šibenik, Croatia on 16–22 September 1991, during the Croatian War of Independence.', 1991, 9, 16, 1991, 9, 22, 'day', '16 September 1991 – 22 September 1991', 39, 'https://en.wikipedia.org/wiki/Battle_of_%C5%A0ibenik'),
  ('Q6016257', 'Independence of Croatia', 'The independence of Croatia was a process started with the changes in the political system and the constitutional changes in 1990 that transformed the Socialist Republic of Croatia into the modern Republic of Croatia, which in turn proclaimed the first Constitution of Croatia, and held the 1991 Croatian independence referendum. After the country formally declared independence in June 1991 and the dissolution of its association with Yugoslavia, it introduced a three-month moratorium on the decision when urged to do so by the European Community and the Conference on Security and Cooperation…', 1991, 10, 8, NULL, NULL, NULL, 'day', '8 October 1991', 43, 'https://en.wikipedia.org/wiki/Independence_of_Croatia'),
  ('Q7096908', 'Battle of Zadar', 'The Battle of Zadar (Croatian: Bitka za Zadar) was a military engagement between the Yugoslav People''s Army (Jugoslovenska Narodna Armija, or JNA), supported by the Croatian Serb Serbian Autonomous Oblast of Krajina (SAO Krajina), and the Croatian National Guard (Zbor Narodne Garde, or ZNG), supported by the Croatian Police. The battle was fought north and east of the city of Zadar, Croatia, in the second half of September and early October 1991 during the Croatian War of Independence.', 1991, 9, 16, 1991, 10, 5, 'day', '16 September 1991 – 5 October 1991', 39, 'https://en.wikipedia.org/wiki/Battle_of_Zadar'),
  ('Q8082793', 'Široka Kula massacre', 'The Široka Kula massacre was the killing of 41 civilians in the village of Široka Kula near Gospić, Croatia during the Croatian War of Independence. The killings began on 13 October 1991 and continued until late October.', 1991, 10, 21, NULL, NULL, NULL, 'day', '21 October 1991', 39, 'https://en.wikipedia.org/wiki/%C5%A0iroka_Kula_massacre'),
  ('Q12639984', 'Paulin Dvor massacre', 'The Paulin Dvor massacre was an act of mass murder committed by soldiers of the Croatian Army (HV) in the village of Paulin Dvor, near the town of Osijek on 11 December 1991 during the Croatian War of Independence. Of the nineteen victims, eighteen were ethnic Serbs, and one was a Hungarian national.', 1991, 12, 11, NULL, NULL, NULL, 'day', '11 December 1991', 39, 'https://en.wikipedia.org/wiki/Paulin_Dvor_massacre'),
  ('Q16858348', '1991 Siege of Kijevo', 'The 1991 siege of Kijevo was one of the earliest clashes of the Croatian War of Independence. The 9th Corps of the Yugoslav People''s Army (JNA) led by Colonel Ratko Mladić and the forces of so-called Serbian Autonomous Oblast (region) of Krajina (SAO Krajina) under Knin police chief Milan Martić besieged the Croat-inhabited village of Kijevo in late April and early May 1991.', 1991, NULL, NULL, 1991, 8, 26, 'year', '1991', 47, 'https://en.wikipedia.org/wiki/Siege_of_Kijevo'),
  ('Q18639132', 'Siege of Bjelovar Barracks', 'The siege of Bjelovar Barracks, also known by the codename Operation Bilogora (Croatian: Operacija Bilogora), was the blockade and capture of the Yugoslav People''s Army (JNA) barracks and other facilities in and around the city of Bjelovar, a part of the JNA 32nd (Varaždin) Corps, during the Croatian War of Independence. A general blockade of the JNA facilities in Croatia was ordered on 14 September 1991, and it continued until 29 September when the JNA garrison was captured by Croatian forces.', 1991, 9, 14, 1991, 9, 29, 'day', '14 September 1991 – 29 September 1991', 41, 'https://en.wikipedia.org/wiki/Siege_of_Bjelovar_Barracks'),
  ('Q1473165', 'Miljevci plateau incident', 'The Battle of the Miljevci Plateau was a clash between the Croatian Army (Hrvatska vojska - HV) and forces of the Republic of Serbian Krajina (RSK), fought on 21–23 June 1992, during the Croatian War of Independence. The battle represented the culmination of a series of skirmishes between the HV and the RSK forces in Northern Dalmatia, after the implementation of the Vance plan and deployment of the United Nations Protection Force (UNPROFOR) began.', 1992, 6, 21, 1992, 6, 23, 'day', '21 June 1992 – 23 June 1992', 45, 'https://en.wikipedia.org/wiki/Battle_of_the_Miljevci_Plateau'),
  ('Q1313538', 'Operation Maslenica', 'Operation Maslenica was a Croatian Army offensive launched in January 1993 to retake territory in northern Dalmatia and Lika from Krajina Serb forces, with the stated military objective of pushing the Serbs back from approaches to Zadar, Maslenica and Karlobag, allowing a secure land route between Dalmatia and northern Croatia to be opened. While an undoubted net Croatian tactical success, the operation was only a moderate strategic success, and was condemned by the UN Security Council.', 1993, 1, 22, 1993, 2, 1, 'day', '22 January 1993 – 1 February 1993', 52, 'https://en.wikipedia.org/wiki/Operation_Maslenica'),
  ('Q1639136', 'Operation Medak Pocket', 'Operation Medak Pocket (Serbo-Croatian: Operacija Medački džep, Операција Медачки џеп), officially called by Croatians Operation Pocket-93 (Operacija Džep-93) was a military operation undertaken by the Croatian Army between 9 – 17 September 1993, in which a salient reaching the south suburbs of Gospić, in the south-central Lika region of Croatia then under the control of the self-proclaimed Republic of Serbian Krajina, was attacked by Croatian forces. The pocket was named after the village of Medak.', 1993, 9, 9, 1993, 9, 17, 'day', '9 September 1993 – 17 September 1993', 53, 'https://en.wikipedia.org/wiki/Operation_Medak_Pocket'),
  ('Q68969', 'Croatian War of Independence', 'The Croatian War of Independence was an armed conflict fought in Croatia from 1991 to 1995 between Croat forces loyal to the Government of Croatia—which had declared independence from the Socialist Federal Republic of Yugoslavia (SFRY)—and the Serb-controlled Yugoslav People''s Army (JNA) and local Serb forces, with the JNA ending its combat operations by 1992. A majority of Croats supported Croatia''s independence from Yugoslavia, while many ethnic Serbs living in Croatia, supported by Serbia, opposed the secession and advocated Serb-claimed lands to be in a common state with Serbia.', 1995, 11, 12, 1995, 8, 7, 'day', '12 November 1995 – 7 August 1995', 79, 'https://en.wikipedia.org/wiki/Croatian_War_of_Independence'),
  ('Q769377', 'Operation Storm', 'Operation Storm (Serbo-Croatian: Operacija Oluja / Операција Олуја) in August 1995 was the last major battle of the Croatian War of Independence and a major factor in the outcome of the Bosnian War. It was a decisive victory for the Croatian Army (HV), which attacked across a 630-kilometre (390 mi) front against the self-declared proto-state Republic of Serbian Krajina (RSK), and a strategic victory for the Army of the Republic of Bosnia and Herzegovina (ARBiH).', 1995, 8, 4, 1995, 8, 7, 'day', '4 August 1995 – 7 August 1995', 69, 'https://en.wikipedia.org/wiki/Operation_Storm'),
  ('Q1374443', 'Operation Flash', 'Operation Flash (Croatian: Operacija Bljesak) was a brief Croatian Army (HV) offensive conducted against the forces of the self-declared proto-state Republic of Serbian Krajina (RSK) from 1–3 May 1995. The offensive occurred in the later stages of the Croatian War of Independence and was the first major confrontation after ceasefire and economic cooperation agreements were signed between Croatia and the RSK in 1994.', 1995, 5, 3, 1995, 5, 4, 'day', '3 May 1995 – 4 May 1995', 59, 'https://en.wikipedia.org/wiki/Operation_Flash'),
  ('Q3540932', 'Split Agreement', 'The Split Agreement or Split Declaration (Serbo-Croatian: Splitski sporazum or Splitska deklaracija) was a mutual defence agreement between Croatia, the Republic of Bosnia and Herzegovina and the Federation of Bosnia and Herzegovina, signed in Split, Croatia on 22 July 1995. It called on the Croatian Army (HV) to intervene militarily in Bosnia and Herzegovina, primarily in relieving the siege of Bihać.', 1995, 7, 22, NULL, NULL, NULL, 'day', '22 July 1995', 47, 'https://en.wikipedia.org/wiki/Split_Agreement'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q88259708', '2020 Zagreb earthquake', 'At approximately 6:24 AM CET on the morning of 22 March 2020, an earthquake of magnitude 5.3 Mw, 5.5 ML, hit Zagreb, Croatia, with an epicenter 7 kilometres (4.3 mi) north of the city centre. The maximum felt intensity was VII–VIII (Very strong to Damaging) on the Medvedev–Sponheuer–Karnik scale.', 2020, 3, 22, NULL, NULL, NULL, 'day', '22 March 2020', 69, 'https://en.wikipedia.org/wiki/2020_Zagreb_earthquake'),
  ('Q104535090', '2020 Petrinja earthquake', 'At 12:19 PM CET (11:19 UTC) on 29 December 2020, an earthquake of magnitude 6.4 Mw (6.2 ML) hit central Croatia, with an epicenter located roughly 3 km (1.9 mi) west-southwest of Petrinja. The maximum felt intensity was estimated at VIII (Heavily damaging) to IX (Destructive) on the European macroseismic scale.', 2020, 12, 29, NULL, NULL, NULL, 'day', '29 December 2020', 68, 'https://en.wikipedia.org/wiki/2020_Petrinja_earthquake'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q121511279', '2023 Slovenia floods', 'In August 2023, major floods occurred in large part of Slovenia and neighbouring areas of Austria and Croatia due to heavy rain. Amongst others, the level of rivers Sava, Mur and Drava was exceptionally high.', 2023, 8, NULL, 2023, 8, 23, 'month', 'August 2023 – 23 August 2023', 43, 'https://en.wikipedia.org/wiki/2023_Slovenia_floods');
